'use strict';

function renderBattlefield(){
  const p=subjectProgress(), next=nextFortress(), sea=seasonInfo(), count=soldiersFor(p.pct);
  let soldiers=''; for(let i=0;i<count;i++)soldiers+=`<div class="soldier"><i class="shield"></i></div>`;
  const siege=p.pct>=45?'<div class="siege" title="Belagerungsgerät freigeschaltet"></div>':'';
  $('#battlefield').className=`battlefield ${sea.class}`; $('#battlefield').setAttribute('aria-label',`${state.activeSubject==='latin'?'Legion':'Armee'}: ${p.pct}% Schuljahresfortschritt, ${next?`nächstes Ziel ${next.name}`:'alle Festungen erreicht'}`);
  $('#battlefield').innerHTML=`<div class="sun"></div>${sea.class==='winter'?'<div class="snow"></div>':''}${sea.festive?`<div class="festive">${state.activeSubject==='latin'?'WINTERLAGER · SATURNALIA':'WINTERLAGER · DEZEMBER-SPEZIAL'}</div>`:''}<div class="army">${soldiers}${siege}</div><div class="fortress ${next?'':'inactive'}"><div class="gate"></div><div class="flag"></div></div>`;
}

